mapper.select:
SELECT u.id AS user_id, u.username, COALESCE(NULLIF(u.nickname,''),u.username) AS name
FROM sys_user u JOIN (
    SELECT user_id FROM afv_canvas_member WHERE canvas_id = #{canvasId}
    UNION SELECT created_by FROM afv_canvas WHERE id = #{canvasId}
    UNION SELECT owner_id FROM afv_canvas WHERE id = #{canvasId} AND owner_type = 1
    UNION SELECT user_id FROM afv_project_member WHERE project_id = #{projectId} AND deleted = FALSE
    UNION SELECT tm.user_id FROM afv_team_member tm JOIN afv_project p ON p.owner_id = tm.team_id
        AND p.owner_type = 2 WHERE p.id = #{projectId} AND tm.deleted = FALSE AND tm.status = 1
) visible ON visible.user_id = u.id
WHERE u.deleted = FALSE ORDER BY u.id
